// Auto-generated from math-background.pdf via base64 (see below to regenerate).
// Embedded directly rather than fetched at runtime, because loading this app via
// file:// (double-clicking index.html) blocks XMLHttpRequest/fetch to local files
// in Chrome/Safari — a different, separate restriction from the ES-module CORS
// issue pdf-viewer.js already works around. Native <script src=...> tag loading
// (this file) is exempt from that restriction, so embedding the bytes here and
// decoding them in JS sidesteps the problem entirely, under file:// or http(s).
//
// To regenerate after replacing math-background.pdf: run this from the project root —
// (note: this overwrites the whole file, including this comment block — restore
// it from here, or from git history once this file is tracked, afterward)
//   node -e "const fs=require('fs');const b64=fs.readFileSync('math-background.pdf').toString('base64');fs.writeFileSync('math-background-pdf-data.js','window.MATH_BACKGROUND_PDF_BASE64 = '+JSON.stringify(b64)+';')"
window.MATH_BACKGROUND_PDF_BASE64 = "";